<?= $this->extend('layouts/staff') ?><?= $this->section('content') ?><?= view('components/page_header',['title'=>'Notifications']) ?><div class="space-y-3"><?php foreach($rows as $row): ?><article class="card flex flex-wrap items-center justify-between gap-3 p-4 <?= $row['read_at']?'opacity-70':'' ?>"><div><h2 class="font-semibold"><?= esc($row['title']) ?></h2><p class="mt-1 text-sm text-gray-600"><?= esc($row['body']) ?></p><time class="mt-1 block text-xs text-gray-500"><?= esc(format_date($row['created_at'])) ?></time></div><?php if(!$row['read_at']): ?><form method="post" action="<?= site_url('notifications/'.$row['id'].'/read') ?>"><?= csrf_field() ?><button class="btn-muted">Mark read</button></form><?php endif ?></article><?php endforeach ?><?php if(!$rows): ?><?= view('components/empty_state',['title'=>'You are all caught up','message'=>'System updates and reminders will appear here.']) ?><?php endif ?></div><div class="mt-4"><?= $pager->links() ?></div><?= $this->endSection() ?>
